function productCard(p){return `<article class="product-card"><a href="#/product/${p.id}" class="product-image"><img src="${asset(p.image)}" alt="${esc(p.name)}" loading="lazy"><span class="product-label">${p.stock>0?'기부 물품':'품절'}</span></a>${btn('wish',icon('heart'),'wish-btn '+(db.wishes.includes(p.id)?'on':''),`data-id="${p.id}" aria-label="${esc(p.name)} 찜" aria-pressed="${db.wishes.includes(p.id)}"`)}<div class="product-body"><a href="#/institution/${p.org}" class="product-org">${icon('leaf')}${esc(org(p.org).name)}</a><a href="#/product/${p.id}"><h3>${esc(p.name)}</h3></a><div class="price"><span class="discount">${Math.round((1-p.price/p.original)*100)}%</span>${money(p.price)}<del>${money(p.original)}</del></div><p class="product-note">이 물건의 다음 주인은, 당신.</p></div></article>`}
function orgCard(o){return `<a href="#/institution/${o.id}" class="org-card"><img class="org-cover" src="${asset(o.cover)}" alt="${esc(o.name)}의 나눔 이미지" loading="lazy"><div class="org-card-body"><span class="org-avatar" style="color:${o.color}">${o.symbol}</span><h3>${esc(o.name)}</h3><p>${esc(o.tag)}</p><small>${esc(o.area)}</small></div></a>`}
function home(){return header()+topNav('/')+`<section class="hero" aria-label="방긋마켓 소식" aria-roledescription="carousel">${heroHTML()}</section><div class="shortcuts">${[['/donate','gift','현물 기부'],['/live','live','라이브 바자회'],['/institutions','shop','기관 쇼핑몰'],['/shop','bag','가치 있는 쇼핑'],['/impact','leaf','나눔 이야기']].map(([url,i,l])=>`<a href="#${url}" class="shortcut"><span class="shortcut-circle">${icon(i)}</span>${l}</a>`).join('')}</div><a href="#/impact" class="impact-strip"><div><small>미리 보는 방긋의 선순환</small><strong>작은 마음이 모여, <em>더 큰 방긋으로</em></strong></div><span class="impact-mark">${icon('smile')}</span></a><section class="section" style="padding-top:0"><div class="section-heading"><div><p class="section-overline">LIVE & GIVE</p><h2>지금, 방긋한 만남</h2></div><a class="text-link" href="#/live">전체 보기${icon('chevron')}</a></div><a href="#/live" class="live-card"><img src="${asset('objects')}" alt="라이브 바자회의 따뜻한 생활용품"><span class="live-tag"><i class="live-dot" style="background:white"></i> LIVE PREVIEW</span><span class="watch-count">방긋 라이브 미리보기</span><div class="live-card-copy"><small>${esc(org(db.live.org).name)}과 함께하는 나눔</small><h3>${esc(db.live.title)}</h3><p>물건 하나에, 마음 하나를 더해요.</p></div><span class="play-button">${icon('play')}</span></a><div class="mini-live"><img src="${asset('hero')}" alt="기부 물품 상자"><div class="mini-live-copy"><small>다음 라이브 · 예시 편성</small><h4>포근한 일상을 위한 작은 선물</h4><p>11. 12 (목) 오후 7:00 · 온기나눔 복지센터</p></div>${btn('alert',icon('bell')+(db.alerts.includes('next')?'알림 설정됨':'알림 받기'),'pill-btn '+(db.alerts.includes('next')?'on':''))}</div></section><section class="section"><div class="section-heading"><div><p class="section-overline">GOOD FINDS, GOOD HEARTS</p><h2>쇼핑에 마음을 더하면<small>마음에 쏙, 나눔에 한 걸음.</small></h2></div><a href="#/shop" class="text-link">더 보기${icon('chevron')}</a></div><div class="chips">${['전체','패션·잡화','리빙·주방','뷰티·케어','도서·취미'].map(c=>btn('home-category',esc(c),'chip '+(c===homeCategory?'active':''),`data-category="${c}"`)).join('')}</div><div class="product-grid">${db.products.filter(p=>homeCategory==='전체'||p.category===homeCategory).slice(0,4).map(productCard).join('')}</div></section><section class="section"><div class="section-heading"><div><p class="section-overline">A PLACE FOR EVERY HEART</p><h2>마음이 닿는 나눔가게<small>응원하고 싶은 기관을 만나 보세요.</small></h2></div><a href="#/institutions" class="text-link">전체 보기${icon('chevron')}</a></div><div class="org-grid">${db.orgs.slice(0,2).map(orgCard).join('')}</div></section><div class="join-banner"><h3>물건의 쓸모는 이어지고,<br>나눔의 미소는 커집니다.</h3><p>기업도 개인도, 마음이 있다면 누구나.<br>방긋마켓과 기분 좋은 나눔을 시작해 보세요.</p><a href="#/donate">현물 기부 알아보기 ${icon('arrow')}</a><span class="gift-symbol">${icon('gift')}</span></div><section class="section"><div class="section-heading"><h2>방긋이 이어지는 이야기</h2><a href="#/impact" class="text-link">더 보기${icon('chevron')}</a></div><a href="#/impact" class="story-card" style="display:block"><span class="story-type">방긋이 꿈꾸는 나눔</span><div class="quote">“</div><h3>한 번의 쇼핑이,<br>누군가에겐 든든한 하루가 되도록.</h3><p>기부 물품이 필요한 사람을 만나고,<br>그 가치가 다시 이웃에게 돌아오는 이야기.</p></a></section>`+footer()+bottomNav()}
function shopPage(){let ps=db.products.filter(p=>(shopCategory==='전체'||p.category===shopCategory)&&(!shopSearch||(p.name+org(p.org).name).includes(shopSearch)));if(shopSort==='low')ps.sort((a,b)=>a.price-b.price);if(shopSort==='high')ps.sort((a,b)=>b.price-a.price);return header()+topNav('/shop')+`<div class="page-head"><div class="eyebrow">THOUGHTFUL SHOPPING</div><h1>오늘도, 가치 있게.</h1><p>언제든 열려 있는 방긋마켓의 상시 바자회.<br>마음에 드는 물건으로 나눔에 함께하세요.</p></div><form id="search-form" class="search-box">${icon('search')}<input name="query" value="${esc(shopSearch)}" placeholder="어떤 좋은 물건을 찾으세요?" aria-label="상품명 또는 기관명 검색"><button aria-label="검색">${icon('arrow')}</button></form><section class="section" style="padding-top:5px"><div class="chips">${['전체','패션·잡화','리빙·주방','뷰티·케어','도서·취미'].map(c=>btn('shop-category',c,'chip '+(c===shopCategory?'active':''),`data-category="${c}"`)).join('')}</div><div class="sort-row"><span>좋은 물건 ${ps.length}개</span><select id="product-sort" aria-label="상품 정렬"><option value="recommend" ${shopSort==='recommend'?'selected':''}>추천순</option><option value="low" ${shopSort==='low'?'selected':''}>낮은 가격순</option><option value="high" ${shopSort==='high'?'selected':''}>높은 가격순</option></select></div><div class="product-grid">${ps.length?ps.map(productCard).join(''):empty('아직 만날 물건이 없어요','다른 검색어나 카테고리로 찾아보세요.',btn('clear-search','전체 상품 보기','secondary-btn'))}</div></section>`+footer()+bottomNav()}
function institutions(){return header()+topNav('/institutions')+`<div class="page-head"><div class="eyebrow">OUR GOOD NEIGHBORS</div><h1>마음이 머무는 나눔가게</h1><p>기관마다 서로 다른 이야기, 같은 따뜻한 마음.<br>기부 물품을 둘러보고, 응원할 곳을 찾아보세요.</p></div><div class="search-box">${icon('search')}<input id="org-search" placeholder="기관 이름, 지역, 나눔 분야 검색" aria-label="기관 검색"></div><section class="section" style="padding-top:5px"><div id="org-results" class="org-grid">${db.orgs.map(orgCard).join('')}</div><div class="info-box">${icon('info')}<span>현재 보이는 기관은 화면 체험을 위한 가상 기관입니다.<br>기관을 선택하면 각 기관의 나눔가게를 볼 수 있어요.</span></div></section>`+footer()+bottomNav()}
function orgPage(id){const o=org(id),ps=db.products.filter(p=>p.org===o.id);const follow=db.follows.includes(id);return header()+`<div class="org-hero"><img src="${asset(o.cover)}" alt="${esc(o.name)} 나눔가게"><div class="org-hero-copy"><small>함께 만드는 우리 기관의 나눔가게</small><h1>${esc(o.tag)}</h1></div></div><section class="org-profile"><div class="split-row"><div class="org-profile-top"><span class="org-avatar" style="color:${o.color}">${o.symbol}</span><div><h2>${esc(o.name)}</h2><span class="verified">${icon('shield')} 사회복지기관 · 예시 나눔가게</span></div></div>${btn('follow',icon('heart')+(follow?'응원 중':'응원하기'),'pill-btn '+(follow?'on':''),`data-id="${id}"`)}</div><p>${esc(o.description)}</p><div class="org-stats"><div><small>판매 상품</small><strong>${ps.length}개</strong></div><div><small>함께하는 마음</small><strong>${o.followers+(follow?1:0)}명</strong></div><div><small>나눔 진행률 · 예시</small><strong style="color:${o.color}">${Math.round(o.raised/o.goal*100)}%</strong></div></div><a href="#/donate?org=${id}" class="primary-btn full green">${icon('gift')} 이 기관에 현물 기부하기</a></section><nav class="org-tabs" aria-label="기관몰 메뉴">${[['goods','판매 상품'],['intro','기관 소개'],['story','나눔 소식'],['report','투명한 나눔']].map(([k,l])=>btn('org-tab',l,orgTab===k?'active':'',`data-tab="${k}"`)).join('')}</nav><section class="section">${orgTab==='goods'?`<div class="section-heading"><h2 style="font-size:17px">우리 기관의 좋은 물건</h2><span class="muted small">상시 바자회 · ${ps.length}개</span></div><div class="product-grid">${ps.length?ps.map(productCard).join(''):empty('새로운 물건을 기다리고 있어요','기부 물품이 등록되면 이곳에서 만날 수 있어요.')}</div>`:orgTab==='intro'?`<div class="story-content"><span class="section-overline">HELLO, NEIGHBOR</span><h2>${esc(o.tag)}<br>작은 마음으로 시작합니다.</h2><p>${esc(o.description)} 방긋마켓 나눔가게는 현물로 전해진 마음이 필요한 이웃에게 다시 닿도록 만들어진 공간입니다.</p><img src="${asset(o.cover)}" alt="나눔의 따뜻한 손길"><h3>기부 물품이 새로운 일상이 되기까지</h3><p>기관이 기부를 접수하고 물품을 확인하면, 방긋마켓이 상품 관리와 라이브 판매, 배송을 함께 진행합니다. 판매 결과와 기관 전달 내역은 투명한 나눔 탭에서 확인할 수 있습니다.</p><div class="info-box">${icon('building')}<span>활동 분야: ${esc(o.area)}<br>운영 기관: ${esc(o.name)} (가상 기관)<br>문의: 방긋마켓 문의하기</span></div></div>`:orgTab==='story'?`<div class="story-content">${publishedNews(o.id)}<h2>함께여서 더 좋은 소식</h2><img src="${asset('community')}" alt="기부 상자를 전하는 손"><h3>물건 하나에 담긴 마음을 전합니다</h3><p>기부자와 구매자, 기관이 함께 만들어 갈 이야기를 이곳에 기록합니다. 앞으로 기관의 활동 후기와 나눔 결과를 만날 수 있어요.</p><span class="mini-badge">미리 보는 기관 소식 · 예시 콘텐츠</span></div>`:`<div class="report-card"><small>이번 달 나눔 현황 · 예시</small><h3>소중한 마음이 이렇게 모였어요</h3><div class="number">${won(o.raised)}</div><div class="progress-track"><span style="width:${Math.min(100,o.raised/o.goal*100)}%"></span></div><div class="split-row small muted"><span>목표 ${won(o.goal)}</span><strong>${Math.round(o.raised/o.goal*100)}%</strong></div></div><div class="report-card"><h3>기관으로 전달되는 과정</h3>${timeline(['현물 기부 접수','물품 검수와 판매 준비','라이브·상시 바자회 판매','배송 및 구매 확정','판매 결과 확인과 기관 정산'])}</div><p class="small muted">표시된 금액은 디자인 예시이며 실제 모금 실적이 아닙니다. 실제 운영 시 판매금액, 비용, 전달금액을 구분하여 공개할 수 있습니다.</p>`}</section>`+footer()+bottomNav()}
function productPage(id){const p=product(id);if(!p)return header()+`<section class="section">${empty('상품을 찾을 수 없어요','다른 좋은 물건을 만나 보세요.','<a href="#/shop" class="primary-btn">바자회로 가기</a>')}</section>`+bottomNav();return header()+`<div class="detail-photo"><img src="${asset(p.image)}" alt="${esc(p.name)}"><a href="#/shop" class="back-float" aria-label="상품 목록으로">${icon('back')}</a>${btn('wish',icon('heart'),'wish-btn '+(db.wishes.includes(id)?'on':''),`data-id="${id}" aria-label="상품 찜"`)}</div><section class="detail-main"><a class="product-org" href="#/institution/${p.org}">${icon('leaf')}${esc(org(p.org).name)}의 판매 상품</a><h1>${esc(p.name)}</h1><div class="price"><span class="discount">${Math.round((1-p.price/p.original)*100)}%</span>${won(p.price)}<del>${won(p.original)}</del></div><div class="detail-benefit">${icon('heart')} 좋은 물건을 고르는 당신의 마음이<br> <b>${esc(org(p.org).name)}</b>의 나눔 활동으로 이어집니다.</div><dl class="detail-spec"><dt>상품 상태</dt><dd>${esc(p.condition)}</dd><dt>기부자</dt><dd>${esc(p.donor)}</dd><dt>남은 수량</dt><dd>${p.stock}개</dd><dt>배송</dt><dd>방긋마켓 통합 배송 · 배송비 3,000원<br>5만원 이상 구매 시 무료 배송</dd></dl><div class="split-row"><span class="small">구매 수량</span><div class="quantity">${btn('qty-minus','−','','aria-label="수량 줄이기"')}<span>${qty}</span>${btn('qty-plus','+','',`data-max="${p.stock}" aria-label="수량 늘리기"`)}</div></div><div class="info-box">${icon('info')}<span>화면 체험용 예시 상품입니다. 실제 결제·배송은 진행되지 않습니다.</span></div></section><section class="section" style="background:#fafbf7"><h3>물건의 새로운 이야기를 시작해요.</h3><p class="story-content">${esc(p.desc)}</p><img src="${asset('community')}" alt="물건과 함께 전해지는 마음" style="width:100%;border-radius:11px;margin:13px 0"><p class="small muted">기부 물품은 기관 쇼핑몰의 판매 상품으로 등록됩니다. 기관은 상품·주문·배송과 정산 내역을 관리하고, 방긋마켓은 자체 라이브 판매를 운영합니다.</p><details><summary>배송 및 교환·반품 안내</summary><p>체험 화면에서는 실제 배송이 이루어지지 않습니다. 정식 운영 시 상품별 배송 일정, 반품 가능 조건과 고객센터 안내가 제공됩니다.</p></details></section><div class="purchase-bar">${btn('add-cart',icon('cart'),'secondary-btn',`data-id="${p.id}" aria-label="장바구니 담기" ${p.stock?'':'disabled'}`)}${btn('buy',p.stock?won(p.price*qty)+' · 구매 체험':'품절되었습니다','primary-btn',`data-id="${p.id}" ${p.stock?'':'disabled'}`)}</div>`+bottomNav()}
function cartPage(checkout=false){const valid=db.cart.filter(c=>product(c.id));let total=valid.reduce((sum,c)=>sum+product(c.id).price*c.qty,0);let ship=total>=50000||!total?0:3000;return header()+`<div class="page-head"><div class="eyebrow">${checkout?'ONE MORE SMILE':'YOUR GOOD FINDS'}</div><h1>${checkout?'마음이 담긴 주문':'나의 장바구니'}</h1><p>${checkout?'마지막 한 걸음, 따뜻한 나눔으로 이어져요.':'마음에 든 물건들을 한자리에 모았어요.'}</p></div><section class="section" style="padding-top:0">${!valid.length?empty('아직 담긴 마음이 없어요','좋은 물건을 만나러 가 볼까요?','<a href="#/shop" class="primary-btn">바자회 둘러보기</a>'):valid.map(c=>{const p=product(c.id);return `<div class="cart-row"><a href="#/product/${p.id}"><img src="${asset(p.image)}" alt="${esc(p.name)}"></a><div class="cart-row-main"><small>${esc(org(p.org).name)}</small><h3>${esc(p.name)}</h3><div class="price">${won(p.price*c.qty)}</div>${!checkout?`<div class="quantity">${btn('cart-minus','−','',`data-id="${p.id}" aria-label="수량 줄이기"`)}<span>${c.qty}</span>${btn('cart-plus','+','',`data-id="${p.id}" aria-label="수량 늘리기"`)}</div>`:`<span class="small muted">${c.qty}개</span>`}</div>${!checkout?btn('cart-remove',icon('close'),'icon-btn',`data-id="${p.id}" aria-label="장바구니에서 삭제"`):''}</div>`}).join('')}${valid.length?`<div class="summary-box"><div class="summary-line"><span>상품 금액</span><span>${won(total)}</span></div><div class="summary-line"><span>배송비</span><span>${ship?won(ship):'무료 배송'}</span></div><div class="summary-line total"><span>주문 체험 금액</span><span>${won(total+ship)}</span></div></div>${checkout?`<form id="checkout-form" class="mt-20"><label class="field">받는 분<input name="name" placeholder="예: 박방긋" required maxlength="30" value="박방긋"></label><label class="field">배송지<input name="address" placeholder="체험용 주소를 입력해 주세요" required maxlength="150" value="서울시 나눔구 방긋로 12 (예시)"></label><div class="info-box warn">${icon('info')}<span>실제 결제가 없는 주문 체험입니다. 실제 주소나 결제 정보를 입력하지 마세요. 주문 내역은 이 브라우저에서만 볼 수 있습니다.</span></div><label class="check-line"><input type="checkbox" required>실제 결제·배송이 없는 체험 주문임을 확인했습니다.</label><button class="primary-btn full">${won(total+ship)} · 주문 체험 완료하기</button></form>`:`<a href="#/checkout" class="primary-btn full mt-20">주문 체험하기 ${icon('arrow')}</a>`}`:''}</section>`+bottomNav()}
function timeline(items){return `<div class="timeline">${items.map((s,i)=>`<div class="timeline-item"><strong>${String(i+1).padStart(2,'0')}. ${s}</strong><p>${['기부자와 기관의 마음을 연결합니다.','기관이 물품 상태와 증빙을 확인합니다.','기관 쇼핑몰과 방긋마켓 라이브에서 판매합니다.','판매 결과를 기관에 공유합니다.','기관의 활동으로 따뜻함을 전합니다.'][i]||''}</p></div>`).join('')}</div>`}
function donatePage(){const pre=currentRoute.split('?org=')[1];if(pre&&donateStep===1)donateDraft.org=pre;if(donateStep===1&&db.role==='company')donateDraft.type='기업';return header()+`<div class="page-head"><div class="eyebrow">GIVE GOODS, GIVE SMILES</div><h1>당신의 물건에, 새로운 내일.</h1><p>개인도 기업도 함께하는 현물 기부.<br>마음이 닿을 곳을 정하고, 첫걸음을 시작하세요.</p></div><div class="stepper">${['기부자 선택','물품과 기관','신청 내용 확인'].map((s,i)=>`<div class="step ${donateStep>=i+1?'active':''}">0${i+1} ${s}</div>`).join('')}</div><section class="section" style="padding-top:0"><form id="donate-form">${donateStep===1?`<div class="type-options">${[['개인','user','작은 물건에도 큰 마음을'],['기업','building','함께 만드는 사회적 가치']].map(([t,i,txt])=>btn('donor-type',icon(i)+`<strong>${t} 기부자</strong><small>${txt}</small>`,'type-option '+(donateDraft.type===t?'selected':''),`data-type="${t}"`)).join('')}</div><label class="field">${donateDraft.type==='기업'?'기업명':'기부자명'}<input name="donor" required placeholder="${donateDraft.type==='기업'?'예: 주식회사 오늘':'예: 김나눔'}" value="${esc(donateDraft.donor||'')}" maxlength="50"></label><label class="field">${donateDraft.type==='기업'?'담당자 이메일':'이메일'}<input type="email" name="email" placeholder="demo@example.com" value="${esc(donateDraft.email||'')}" required><small>화면 체험에는 가상의 정보를 사용해 주세요.</small></label><div class="info-box">${icon('gift')}<span>기부 신청 → 기관 확인·검수 → 판매 → 기관 정산<br>기부금 영수증은 수령 기관의 검토·발급 절차로 이어집니다.</span></div>`:donateStep===2?`<label class="field">마음을 전할 기관<select name="org">${db.orgs.map(o=>`<option value="${o.id}" ${donateDraft.org===o.id?'selected':''}>${esc(o.name)} · ${esc(o.area)}</option>`).join('')}</select></label><label class="field">기부 물품명<input name="name" required maxlength="80" placeholder="예: 미사용 머그컵" value="${esc(donateDraft.name||'')}"></label><div class="field-row"><label class="field">수량<input name="qty" type="number" min="1" max="100000" required value="${donateDraft.qty||1}"></label><label class="field">상품 상태<select name="condition"><option>미사용 새 상품</option><option>미개봉 새 상품</option><option>기관 확인 필요</option></select></label></div><label class="field">참고 가액 합계 (원)<input type="number" name="value" min="0" max="10000000000" step="1" placeholder="예: 120000" value="${donateDraft.value||''}"><small>기부자가 입력하는 참고 금액입니다. 영수증 발급 가액으로 자동 확정되지 않습니다.</small></label><label class="field">전하고 싶은 내용<textarea name="memo" placeholder="물품 설명, 수거·배송 희망 사항 등을 남겨 주세요.">${esc(donateDraft.memo||'')}</textarea></label><label class="check-line"><input type="checkbox" name="receipt" ${donateDraft.receipt?'checked':''}>수령 기관에 기부금 영수증 발급 검토를 요청합니다.</label>`:`<div class="report-card"><h3>전할 마음을 확인해 주세요</h3><div class="metrics-list"><div><span>기부자</span><strong>${esc(donateDraft.donor)} · ${donateDraft.type}</strong></div><div><span>기부 물품</span><strong>${esc(donateDraft.name)} ${donateDraft.qty}개</strong></div><div><span>받는 기관</span><strong>${esc(org(donateDraft.org).name)}</strong></div><div><span>참고 가액</span><strong>${won(donateDraft.value)}</strong></div><div><span>영수증 검토 요청</span><strong>${donateDraft.receipt?'요청':'미요청'}</strong></div></div></div><div class="info-box">${icon('shield')}<span>기관이 물품과 증빙을 확인한 뒤 접수를 진행합니다. 기관은 쇼핑몰의 상품·주문·배송을 관리하고, 방긋마켓은 자체 라이브 판매를 운영합니다.</span></div><label class="check-line"><input type="checkbox" required>가상의 정보로 진행하는 기부 신청 체험임을 확인했습니다.</label>`}<div class="form-actions">${donateStep>1?btn('donate-prev','이전','secondary-btn'):''}<button class="primary-btn">${donateStep===3?'기부 신청 체험 완료하기':'다음으로'} ${icon('arrow')}</button></div></form></section>`+bottomNav()}
function livePage(){return header()+topNav('/live')+`<div class="page-head"><div class="eyebrow">MEET LIVE, GIVE LOVE</div><h1>함께 보면 더 방긋.</h1><p>방긋마켓이 직접 준비하는 라이브 바자회.</p></div><div class="live-stage"><img src="${asset('objects')}" alt="라이브 스튜디오 예시 화면"><span class="stage-label live-tag">${db.live.status==='진행 중'?'방송 시뮬레이션':'LIVE PREVIEW'}</span><div class="stage-center">${btn('live-preview',icon('play'),'play-disc','aria-label="라이브 미리보기 안내"')}<p>라이브 바자회 · 화면 미리보기</p></div><div class="stage-bottom"><span>방긋마켓 자체 운영</span><span>실시간 송출 미연결</span></div></div><section class="section"><h2 style="font-size:21px;margin:0 0 9px">${esc(db.live.title)}</h2><a href="#/institution/${db.live.org}" class="product-org">${icon('leaf')}${esc(org(db.live.org).name)}와 함께해요</a><div class="chat-panel" id="chat-list"><div><b>방긋지기</b>좋은 물건과 따뜻한 마음이 만나는 시간이에요.</div><div><b>안내</b>라이브와 채팅은 체험 화면으로 제공됩니다.</div>${chatMessages.map(m=>`<div><b>나</b>${esc(m)}</div>`).join('')}</div><form id="chat-form" class="chat-input"><input name="message" aria-label="채팅 체험" maxlength="140" required placeholder="방긋한 인사를 남겨 보세요"><button>보내기</button></form><div class="section-heading mt-20"><h2 style="font-size:17px">오늘 라이브에서 만날 물건</h2><span class="small muted">구매 체험</span></div><div class="product-grid">${db.live.products.map(product).filter(Boolean).map(productCard).join('')}</div></section><section class="section"><div class="section-heading"><h2>다음 방긋을 기다리며</h2></div><div class="mini-live" style="padding:0"><img src="${asset('hero')}" alt="다음 라이브 포스터"><div class="mini-live-copy"><small>예시 편성 · 11.12 (목) 19:00</small><h4>포근한 일상을 위한 작은 선물</h4><p>온기나눔 복지센터와 함께</p></div>${btn('alert',icon('bell')+(db.alerts.includes('next')?'설정됨':'알림'),'pill-btn '+(db.alerts.includes('next')?'on':''))}</div></section>`+footer()+bottomNav()}
function impactPage(){return header()+`<div class="page-head"><div class="eyebrow">SMALL ACTS, LASTING SMILES</div><h1>마음이 흐르는 길.</h1><p>물건에 담긴 마음이 꼭 필요한 곳에 닿을 때까지,<br>방긋마켓이 함께합니다.</p></div><img src="${asset('community')}" alt="나눔의 물품을 전하는 손길" style="width:100%;height:280px;object-fit:cover"><section class="section story-content"><h2>사는 즐거움이,<br>나누는 기쁨으로 이어지도록.</h2><p>누군가에게는 더 이상 쓰이지 않는 물건도, 다른 누군가에겐 꼭 필요한 물건입니다. 방긋마켓은 그 사이를 연결해 현물 기부가 기관의 활동을 위한 자금으로 이어지게 합니다.</p>${timeline(['개인·기업의 현물 기부','기관의 물품 수령과 확인','기관 쇼핑몰·자체 라이브 판매','기관별 판매금액 확인','기관에 판매대금 정산'])}<div class="report-card"><h3>판매와 정산, 한눈에.</h3><div class="metrics-list"><div><span>상품 판매금액 · 예시</span><strong>1,000,000원</strong></div><div><span>운영 비용 · 예시 설정 5%</span><strong>50,000원</strong></div><div><span>기관 전달 예정액 · 예시</span><strong style="color:var(--green)">950,000원</strong></div></div><p class="small muted">정산 구조를 보여 주는 예시입니다. 실제 수수료와 비용은 운영 정책 확정 후 반영됩니다.</p></div><h3>기부하는 마음도 소중하게</h3><p>기부자와 물품을 수령한 기관, 판매 상품을 연결합니다. 기관은 접수·증빙을 확인하고 기부금 영수증 발급 업무를 관리할 수 있습니다.</p><a href="#/donate" class="primary-btn full">나의 마음 더하기 ${icon('gift')}</a></section>`+footer()+bottomNav()}
function myPage(){return header()+`<div class="page-head"><div class="eyebrow">MY LITTLE GOOD</div><h1>${db.role?esc(db.profile.name)+'님, 반가워요.':'당신의 방긋을 모아 보세요.'}</h1><p>나눔과 쇼핑, 작은 마음이 쌓이는 나만의 공간.</p></div><section class="section" style="padding-top:0"><div class="report-card"><div class="split-row"><div><h3>${db.role?roleLabels[db.role]:'방긋마켓에 오신 걸 환영해요'}</h3><span class="small muted">${db.role?'역할별 화면을 체험하고 있어요.':'구매와 기부, 다양한 역할을 둘러보세요.'}</span></div>${icon('smile')}</div>${btn('roles',db.role?'역할 전환하기':'계정·콘솔 체험하기','primary-btn full mt-20')}${db.role&&db.role!=='buyer'?'<a href="#/console" class="secondary-btn full mt-20">'+icon('settings')+' 내 콘솔 열기</a>':''}</div><div class="section-heading"><h2 style="font-size:18px">최근 주문</h2><span class="small muted">체험 내역</span></div>${orderList(db.orders.filter(o=>AccountCore.owns(db,o)))}<div class="section-heading mt-20"><h2 style="font-size:18px">마음에 담은 물건</h2><span class="small muted">${db.wishes.length}개</span></div><div class="product-grid">${db.wishes.map(product).filter(Boolean).map(productCard).join('')||empty('마음에 드는 물건을 찜해 보세요','상품의 하트를 눌러 담을 수 있어요.')}</div><div class="section-heading mt-20"><h2 style="font-size:18px">응원하는 나눔가게</h2></div><div class="org-grid">${db.follows.map(org).map(orgCard).join('')||empty('응원할 기관을 만나 보세요','기관몰에서 응원하기를 눌러 보세요.','<a href="#/institutions" class="secondary-btn">나눔가게 둘러보기</a>')}</div><div class="info-box">${icon('info')}<span>체험 데이터는 이 브라우저에 저장됩니다. 다른 역할의 콘솔에서도 같은 체험 주문과 기부 신청을 확인할 수 있습니다.</span></div>${db.role?btn('logout','체험 계정 나가기','secondary-btn full'):''}</section>`+footer()+bottomNav()}
function orderList(orders,ops=false){return orders.length?`<div class="data-list">${orders.map(o=>`<div class="data-row"><img src="${asset(product(o.items[0]?.id)?.image||'hero')}" alt="주문 상품"><div class="data-row-content"><p>${esc(o.id)} · ${o.date}</p><h3>${esc(product(o.items[0]?.id)?.name||'상품')} ${o.items.length>1?'외 '+(o.items.length-1)+'종':''}</h3><strong>${won(o.total)}</strong><p>${o.tracking?'운송장 '+esc(o.tracking):esc(o.name)}</p></div><div class="data-row-side">${status(o.status)}${ops?btn('order-manage','주문 관리','',`data-id="${o.id}"`):btn('order-detail','상세 보기','',`data-id="${o.id}"`)}</div></div>`).join('')}</div>`:empty('아직 주문 내역이 없어요','상품을 담고 주문 체험을 진행해 보세요.','<a href="#/shop" class="secondary-btn">상품 둘러보기</a>')}
const menus={individual:[['dashboard','대시보드'],['donations','기부 신청 내역'],['tracking','기부 진행 현황'],['receipts','기부금 영수증'],['partners','연결 기관'],['reports','나눔 리포트'],['settings','내 정보']],company:[['dashboard','대시보드'],['donations','현물 기부 관리'],['tracking','물품 진행 현황'],['receipts','기부금 영수증'],['partners','파트너 기관'],['reports','ESG 나눔 리포트'],['team','담당자 관리'],['settings','기업 정보']],agency:[['dashboard','기관 대시보드'],['intake','기부 접수·검수'],['goods','기부 상품'],['sales','판매 내역'],['settlements','정산 관리'],['donors','기부자 관리'],['receipts','영수증 발급'],['mall','기관몰 꾸미기'],['news','나눔 소식'],['reports','운영 리포트'],['settings','기관 정보']],admin:[['dashboard','운영 대시보드'],['studio','라이브 스튜디오'],['donations','현물 기부 접수'],['products','상품 관리'],['inventory','입고·재고'],['matching','기부자·기관 매칭'],['orders','주문 관리'],['shipping','배송 관리'],['settlements','기관 정산'],['institutions','기관 관리'],['members','계정·승인'],['receipts','영수증 현황'],['campaigns','배너·기획전'],['analytics','통합 리포트'],['notices','공지 관리'],['settings','운영 설정']]};
const scopedDonations=()=>db.donations.filter(d=>db.role==='admin'||(db.role==='agency'?d.org===db.orgId:d.ownerAccount?d.ownerAccount===MarketCore.accountId(db):db.role==='company'?d.type==='기업'&&(d.donor==='주식회사 오늘'||d.mine):db.role==='individual'&&d.type==='개인'&&(d.donor==='김나눔'||d.mine)));
const scopedProducts=()=>db.products.filter(p=>db.role!=='agency'||p.org===db.orgId);
const scopedSales=()=>db.orders.filter(o=>o.items.some(i=>db.role!=='agency'||product(i.id)?.org===db.orgId)).map(o=>{if(db.role!=='agency')return o;const items=o.items.filter(i=>product(i.id)?.org===db.orgId);return {...o,items,total:items.reduce((a,i)=>a+(product(i.id)?.price||0)*i.qty,0)}});
const scopedSettlements=()=>db.settlements.filter(s=>db.role!=='agency'||s.org===db.orgId);
function consolePage(){if(!db.role||db.role==='buyer')return header()+`<div class="page-head"><h1>나의 방긋 워크스페이스</h1><p>각 역할에 맞는 콘솔을 둘러보세요.</p></div><section class="section">${roleOptions()}</section>`+bottomNav();let menu=menus[db.role];if(!menu.some(x=>x[0]===consoleSection))consoleSection='dashboard';let title=db.role==='agency'?activeOrg().name:db.role==='company'?db.profile.name:db.role==='individual'?db.profile.name:'방긋 운영팀';return header(true)+`<div class="console-strip"><span>디자인 체험 · ${roleLabels[db.role]} 콘솔</span>${btn('roles','역할 전환','')}</div><div class="console-welcome"><div class="eyebrow">${db.role==='admin'?'BANGGEUT OPERATIONS':db.role==='agency'?'INSTITUTION WORKSPACE':db.role==='company'?'CORPORATE GIVING':'MY GIVING WORKSPACE'}</div><h1>${esc(title)}, 오늘도 방긋.</h1><p>${db.role==='admin'?'기부부터 판매, 기관 정산까지 한곳에서 관리하세요.':db.role==='agency'?'전해진 마음을 확인하고, 더 큰 나눔으로 이어 주세요.':'내가 전한 마음이 어디까지 닿았는지 확인해 보세요.'}</p>${db.role==='agency'?`<select id="agency-switch" aria-label="기관 콘솔 체험 전환" style="margin-top:13px;border:1px solid #e6ebdf;padding:7px;border-radius:6px;background:#fff;font-size:10px">${db.orgs.map(o=>`<option value="${o.id}" ${o.id===db.orgId?'selected':''}>${esc(o.name)} · 체험</option>`).join('')}</select>`:''}</div><nav class="console-menu" aria-label="${roleLabels[db.role]} 콘솔 메뉴">${menu.map(([k,l])=>btn('console-tab',l,consoleSection===k?'active':'',`data-section="${k}"`)).join('')}</nav><section class="section" id="console-content">${consoleContent()}</section><div style="padding:0 23px 20px"><div class="demo-line">데모 콘솔 · 변경 내용은 이 브라우저에만 저장됩니다.<br>실제 계정 권한·송출·결제·송금·공식 영수증 발급은 연결 전입니다.</div></div>`+bottomNav()}
const consoleTitle=(title,sub='',button='')=>`<div class="console-title"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${button}</div>`;
const statCard=(label,value,note='',highlight=false)=>`<div class="stat-card ${highlight?'highlight':''}"><small>${label}</small><strong>${value}</strong><em>${note}</em></div>`;
function consoleContent(){const role=db.role,sec=consoleSection,ds=scopedDonations(),ps=scopedProducts(),ss=scopedSettlements();
if(sec==='dashboard'){const amount=role==='admin'?db.orders.reduce((a,o)=>a+o.total,0):role==='agency'?activeOrg().raised:ds.reduce((a,d)=>a+d.value,0);return `<div class="stat-grid">${statCard(role==='admin'?'누적 주문 체험액':role==='agency'?'누적 판매금액 · 예시':'현물 참고 가액 · 예시',won(amount),'이번 달 나눔을 모았어요',true)}${statCard(role==='agency'?'정산 예정액':role==='admin'?'판매 중인 상품':'기부 신청',role==='agency'?won(ss.filter(s=>s.status!=='정산 완료').reduce((a,s)=>a+s.net,0)):role==='admin'?ps.length+'개':ds.length+'건','함께 이어 가는 따뜻한 마음')}${statCard(role==='admin'?'연결 기관':role==='agency'?'기부 접수':'판매 상품',role==='admin'?db.orgs.length+'곳':role==='agency'?ds.length+'건':ds.reduce((a,d)=>a+d.qty,0)+'개','예시 데이터 포함')}${statCard(role==='admin'?'처리 대기 주문':role==='agency'?'발급 검토 요청':'영수증 진행',role==='admin'?db.orders.filter(o=>o.status==='상품 준비 중').length+'건':ds.filter(d=>!d.receipt.includes('완료')).length+'건','확인이 필요한 항목')}</div>${role==='admin'?`<div class="event-mini"><strong>오늘의 운영 체크</strong>상품 준비 주문 ${db.orders.filter(o=>o.status==='상품 준비 중').length}건 · 기부 검수 ${db.donations.filter(d=>d.status==='입고 검수').length}건 · 기관 정산 ${db.settlements.filter(s=>s.status==='정산 대기').length}건</div><div class="button-group">${btn('console-tab',icon('live')+' 방송 준비','primary-btn green','data-section="studio"')}${btn('product-new',icon('box')+' 상품 등록','secondary-btn')}${btn('console-tab','기관 정산 확인','secondary-btn','data-section="settlements"')}</div>`:role==='agency'?`<div class="button-group"><a class="primary-btn green" href="#/institution/${db.orgId}">${icon('shop')} 기관몰 보기</a>${btn('console-tab','기부 접수 확인','secondary-btn','data-section="intake"')}</div>`:`<a href="#/donate" data-donor-start="${role}" class="primary-btn full">${icon('gift')} 새로운 현물 기부 신청</a>`}<div class="report-card mt-20"><h3>${role==='admin'?'나눔 운영 흐름':role==='agency'?'우리 기관의 나눔 흐름':'내 마음이 이어지는 과정'}</h3>${timeline(role==='admin'||role==='agency'?['기부 접수·기관 연결','현물 수령·증빙 검토','기부 상품 등록·판매','주문 배송·판매 확정','기관 정산·결과 공유']:['마음을 전할 기관 선택','현물 기부 신청 접수','기관의 수령·검수 확인','상품 판매와 나눔 진행','기관의 소식과 영수증 확인'])}</div>${consoleTitle('최근 '+(role==='admin'?'기부 접수':'나눔 내역'))}${donationList(ds.slice(0,3))}`}
if(['donations','intake','tracking'].includes(sec)){return consoleTitle(sec==='tracking'?'기부 물품의 지금':sec==='intake'?'마음을 받고, 물품을 확인해요':'현물 기부 신청 내역','기부자 · 물품 · 수령 기관을 함께 관리합니다.',role==='individual'||role==='company'?'<a href="#/donate" class="pill-btn">+ 새 기부</a>':'')+donationList(ds,role==='admin'||role==='agency')+`<div class="info-box">${icon('info')}<span>기부 가액은 증빙과 물품 검토를 거쳐 확인합니다. 영수증 발급 단계는 수령 기관 콘솔에서 관리할 수 있습니다.</span></div>`}
if(['products','goods','inventory'].includes(sec)){return consoleTitle(sec==='inventory'?'입고부터 판매까지, 재고 관리':sec==='goods'?'우리 기관에 연결된 기부 상품':'기부 상품 관리',role==='agency'?'방긋마켓 운영팀이 등록·판매하는 상품을 확인합니다.':'상품과 기부자, 기관을 연결하고 판매 상태를 관리하세요.',role==='admin'?btn('product-new','+ 상품 등록','pill-btn'):'')+(sec==='inventory'?`<div class="stat-grid">${statCard('총 재고',ps.reduce((a,p)=>a+p.stock,0)+'개','현재 판매 가능 수량')}${statCard('재고 10개 이하',ps.filter(p=>p.stock<=10).length+'종','재고를 확인해 주세요',true)}</div>`:'')+`<div class="data-list">${ps.map(p=>`<div class="data-row"><img src="${asset(p.image)}" alt="${esc(p.name)}"><div class="data-row-content"><h3>${esc(p.name)}</h3><p>${esc(org(p.org).name)} · ${esc(p.donor)}</p><strong>${won(p.price)}</strong></div><div class="data-row-side">${status('재고 '+p.stock+'개')}${role==='admin'?btn('product-edit',sec==='inventory'?'재고 수정':'상품 수정','',`data-id="${p.id}"`):`<a href="#/product/${p.id}" class="text-link">상품 보기</a>`}</div></div>`).join('')}</div>`}
if(sec==='matching'){return consoleTitle('기부자와 기관, 물품을 연결해요','물품별 수령 기관과 판매 상품을 함께 지정합니다.',btn('matching','+ 매칭 관리','pill-btn'))+`<div class="data-list">${db.donations.map(d=>`<div class="data-row"><span style="color:var(--green)">${icon(d.type==='기업'?'building':'user')}</span><div class="data-row-content"><h3>${esc(d.donor)} → ${esc(org(d.org).name)}</h3><p>${esc(d.name)} · ${d.qty}개<br>${esc(d.id)} · ${d.type} 기부자</p></div><div class="data-row-side">${status('기관 연결됨')}${btn('matching','변경','',`data-id="${d.id}"`)}</div></div>`).join('')}</div>`}
if(['orders','shipping','sales'].includes(sec)){let orders=scopedSales();if(sec==='shipping')orders=orders.filter(o=>o.status!=='주문 취소');return consoleTitle(sec==='shipping'?'배송 진행 현황':sec==='sales'?'우리 기관의 상품 판매 내역':'주문 관리','주문 상품과 연결 기관, 배송 상태를 확인합니다.',btn('export',icon('download')+' CSV','pill-btn',`data-kind="orders"`))+orderList(orders,role==='admin')}
if(sec==='settlements'){let pending=ss.filter(s=>s.status!=='정산 완료').reduce((a,s)=>a+s.net,0);return consoleTitle('기관별 정산을 투명하게','판매금액과 운영 비용, 기관 전달액을 구분합니다.',btn('export',icon('download')+' CSV','pill-btn','data-kind="settlements"'))+`<div class="stat-grid">${statCard('정산 예정 금액',won(pending),'데모 정산 현황',true)}${statCard('누적 정산 완료',won(ss.filter(s=>s.status==='정산 완료').reduce((a,s)=>a+s.net,0)),'실제 송금 미연결')}</div><div class="data-list">${ss.map(s=>`<div class="data-row"><div class="data-row-content"><p>${s.period} · ${esc(s.id)}</p><h3>${esc(org(s.org).name)}</h3><strong>${won(s.net)}</strong><p>판매 ${won(s.gross)} − 운영 비용 ${won(s.fee)}</p></div><div class="data-row-side">${status(s.status)}${s.status==='정산 완료'?btn('settlement-detail','명세서','',`data-id="${s.id}"`):role==='admin'?btn('settlement-review','정산 처리','',`data-id="${s.id}"`):btn('settlement-request',s.status==='요청 접수'?'요청 내역':'정산 요청','',`data-id="${s.id}"`)}</div></div>`).join('')}</div><div class="info-box warn">${icon('info')}<span>정산 시뮬레이션입니다. 실제 계좌 이체가 발생하지 않습니다. 수수료는 화면 예시로, 운영 설정에서 변경할 수 있습니다.</span></div>`}
if(sec==='receipts'){return consoleTitle(role==='agency'?'수령 기관의 영수증 검토·발급':'기부금 영수증 현황','기부 현물과 참고 가액, 증빙 확인 상태를 함께 봅니다.')+`<div class="data-list">${ds.map(d=>`<div class="data-row"><span style="color:var(--green)">${icon('file')}</span><div class="data-row-content"><h3>${esc(d.donor)} · ${esc(d.name)}</h3><p>${esc(org(d.org).name)}<br>참고 가액 ${won(d.value)} · ${d.date}</p></div><div class="data-row-side">${status(d.receipt)}${btn('receipt-view',role==='agency'?'검토·샘플 발급':'상세·샘플 보기','',`data-id="${d.id}"`)}</div></div>`).join('')||empty('아직 영수증 검토 내역이 없어요','현물 기부를 신청하면 이곳에서 확인할 수 있어요.')}</div><div class="info-box">${icon('shield')}<span>공식 영수증 발급 연동 전입니다. 체험 중 생성되는 문서는 세무 증빙으로 사용할 수 없는 샘플입니다.</span></div>`}
if(['partners','donors','institutions'].includes(sec)){return consoleTitle(sec==='donors'?'우리 기관과 마음을 나눈 기부자':sec==='institutions'?'파트너 사회복지기관':'내 마음이 닿은 기관',sec==='institutions'?'기관 현황과 기관몰을 함께 관리합니다.':'기부 물품과 기관의 연결 관계를 확인합니다.',role==='admin'?btn('institution-new','+ 기관 등록','pill-btn'):'')+(sec==='donors'?`<div class="data-list">${ds.map(d=>`<div class="data-row">${icon(d.type==='기업'?'building':'user')}<div class="data-row-content"><h3>${esc(d.donor)}</h3><p>${d.type} · ${esc(d.name)} ${d.qty}개</p></div><div class="data-row-side">${status(d.status)}${btn('donation-detail','상세 보기','',`data-id="${d.id}"`)}</div></div>`).join('')}</div>`:`<div class="org-grid">${(role==='admin'?db.orgs:db.orgs.filter(o=>ds.some(d=>d.org===o.id))).map(orgCard).join('')||empty('연결된 기관을 기다리고 있어요','현물 기부를 시작해 마음을 전해 보세요.')}</div>`)}
if(['reports','analytics'].includes(sec)){return consoleTitle(role==='company'?'우리 기업의 ESG 나눔 기록':'한눈에 보는 방긋 리포트','현재 체험 데이터와 예시 차트로 보는 나눔 흐름',btn('export',icon('download')+' CSV','pill-btn','data-kind="report"'))+`<div class="stat-grid">${statCard('기부 물품',ds.reduce((a,d)=>a+d.qty,0)+'개','마음이 담긴 물품',true)}${statCard('함께한 기관',new Set(ds.map(d=>d.org)).size+'곳','가치 있는 연결')}${statCard('참고 가액',won(ds.reduce((a,d)=>a+d.value,0)),'확정 기부 가액이 아닙니다')}${statCard('기부 신청',ds.length+'건','예시 내역 포함')}</div><div class="report-card"><h3>나눔의 발걸음 · 예시 차트</h3><div class="console-chart">${[35,52,43,72,63,95].map((h,i)=>`<div class="bar-wrap"><div class="bar" style="height:${h}%"></div><small>${i+6}월</small></div>`).join('')}</div></div><div class="report-card"><h3>현물 기부와 판매 결과 연결</h3><div class="metrics-list">${ds.map(d=>`<div><span>${esc(d.name)}</span><strong>${d.qty}개 · ${esc(d.status)}</strong></div>`).join('')}</div><p class="small muted">정식 운영 시 입고·판매·반품·정산 데이터를 기준으로 기간별 리포트를 제공합니다.</p></div>`}
if(sec==='team'){return consoleTitle('나눔을 함께하는 담당자','기업 담당자를 추가해 역할 구성을 체험하세요.',btn('team-new','+ 담당자 추가','pill-btn'))+`<div class="data-list">${db.team.map((m,i)=>`<div class="data-row">${icon('user')}<div class="data-row-content"><h3>${esc(m.name)} · ${esc(m.role)}</h3><p>${esc(m.email)}</p></div>${btn('team-remove',icon('close'),'icon-btn',`data-index="${i}" aria-label="담당자 삭제"`)}</div>`).join('')}</div><div class="info-box">${icon('info')}<span>팀 구성 화면 체험입니다. 실제 계정 초대나 이메일 발송은 진행되지 않습니다.</span></div>`}
if(sec==='mall'){const o=activeOrg();return consoleTitle('기관의 이야기가 보이는 나눔가게','PC에서도 모바일 폭과 여백 이미지를 유지합니다.','<a class="pill-btn" href="#/institution/'+o.id+'">기관몰 보기</a>')+`<form id="mall-form" class="form-box"><label class="field">기관몰 이름<input name="name" required value="${esc(o.name)}" maxlength="40"></label><label class="field">기관몰 한 줄 소개<input name="tag" required value="${esc(o.tag)}" maxlength="50"></label><label class="field">기관 소개<textarea name="description" required maxlength="300">${esc(o.description)}</textarea></label><label class="field">활동 지역·분야<input name="area" value="${esc(o.area)}" maxlength="50"></label><div class="field">기관의 포인트 색상<div class="color-choice">${['#477560','#c99551','#6a7b93','#be805e'].map(c=>btn('mall-color','',''+(o.color===c?'active':''),`style="background:${c}" data-color="${c}" aria-label="색상 ${c}"`)).join('')}</div></div><div class="field">기관몰 배너·PC 여백 이미지<div class="cover-options">${['people','community','bazaar'].map(c=>btn('mall-cover',`<img src="${asset(c)}" alt="${c==='people'?'사람들이 함께하는 바자회':c==='bazaar'?'현장 바자회':'기부의 손길'}">`,o.cover===c?'active':'',`data-cover="${c}"`)).join('')}</div><small>선택한 이미지는 기관몰 상단과 PC 여백에 함께 적용됩니다.</small></div><button class="primary-btn full green">기관몰 저장하기</button></form>`}
if(sec==='news'||sec==='notices'){return consoleTitle(sec==='news'?'나눔가게 소식':'방긋마켓 공지 관리','새로운 소식을 작성하고 게시 상태를 관리하세요.',btn('notice-new','+ 소식 작성','pill-btn'))+`<div class="data-list">${db.notices.filter(n=>role==='admin'||n.org===db.orgId).map(n=>`<div class="data-row"><div class="data-row-content"><h3>${esc(n.title)}</h3><p>${esc(n.body)}<br>${esc(n.date)}</p></div><div class="data-row-side">${status(n.status)}${btn('notice-toggle',n.status==='게시 중'?'비공개로':'게시하기','',`data-id="${n.id}"`)}</div></div>`).join('')||empty('새로운 나눔 이야기를 기다려요','기관의 활동과 나눔 소식을 기록해 보세요.')}</div>`}
if(sec==='members'){return consoleTitle('함께하는 계정과 기관 승인','계정 유형별 승인 상태를 확인하고 변경합니다.')+`<div class="data-list">${db.members.map((m,i)=>`<div class="data-row">${icon(m.type.includes('기관')?'building':'user')}<div class="data-row-content"><h3>${esc(m.name)}</h3><p>${esc(m.type)}</p></div><div class="data-row-side">${status(m.status)}${btn('member-toggle',m.status==='활성'?'이용 정지':'승인·활성화','',`data-index="${i}"`)}</div></div>`).join('')}</div>`}
if(sec==='campaigns'){return consoleTitle('메인 배너와 기획전','생성형 이미지와 메시지로 방긋의 첫인상을 만듭니다.')+`<div class="data-list">${slides.map((s,i)=>{s={...s,...db.banners[i]};return `<div class="data-row"><img src="${asset(s.image)}" alt="배너 ${i+1}"><div class="data-row-content"><p>메인 배너 0${i+1}</p><h3>${s.title}</h3></div><div class="data-row-side">${status('노출 중')}${btn('banner-edit','배너 수정','',`data-index="${i}"`)}</div></div>`}).join('')}</div><div class="info-box">${icon('info')}<span>메인 4개 배너가 자동 순환합니다. 제목과 이미지를 변경해 메인에서 확인해 보세요.</span></div>`}
if(sec==='studio'){return studioPage()}
if(sec==='settings'){return consoleTitle(role==='admin'?'방긋 운영 설정':role==='agency'?'기관 기본 정보':role==='company'?'기업 정보 관리':'나의 기본 정보','체험 정보로 저장하고 화면에서 확인하세요.')+`<form id="settings-form" class="form-box">${role==='admin'?`<label class="field">서비스명<input name="name" value="${esc(db.settings.name)}" required maxlength="30"></label><label class="field">운영 비용 비율 · 예시 (%)<input name="fee" type="number" min="0" max="50" step="0.1" value="${db.settings.fee}" required><small>이후 생성되는 체험 정산에 적용됩니다.</small></label><label class="field">문의 운영 시간<input name="support" value="${esc(db.settings.support)}" required></label>`:role==='agency'?`<label class="field">기관명<input name="name" value="${esc(activeOrg().name)}" required maxlength="40"></label><label class="field">기관 담당자 이메일<input name="email" type="email" value="${esc(activeOrg().email||'agency@example.com')}" required></label><label class="field">정산 계좌 표시 정보<input name="account" value="${esc(activeOrg().account||'방긋은행 · 000-***-0000 (예시)')}" required><small>실제 계좌번호는 입력하지 마세요. 체험용 표시 정보입니다.</small></label>`:`<label class="field">${role==='company'?'기업명':'대화명'}<input name="name" value="${esc(db.profile.name)}" required maxlength="40"></label><label class="field">이메일<input name="email" type="email" value="${esc(db.profile.email)}" required></label>${role==='company'?'<label class="field">사업자 등록 정보<input name="business" placeholder="000-00-00000 (예시)" value="'+esc(db.profile.business||'')+'"><small>실제 사업자등록번호를 입력하지 마세요.</small></label>':''}`}<button class="primary-btn full green">설정 저장</button></form><div class="info-box">${icon('info')}<span>이 브라우저의 데모 설정입니다. 실제 계정·권한은 변경되지 않습니다.</span></div>${btn('reset-demo','체험 데이터 초기화','secondary-btn full')}`}
return empty('다음 나눔을 준비하고 있어요','대시보드에서 현재 나눔 현황을 확인해 보세요.');}
function donationList(ds,ops=false){return ds.length?`<div class="data-list">${ds.map(d=>`<div class="data-row"><span style="color:var(--green)">${icon('gift')}</span><div class="data-row-content"><p>${esc(d.id)} · ${esc(d.date)}</p><h3>${esc(d.name)} · ${d.qty}개</h3><p>${esc(d.donor)} → ${esc(org(d.org).name)}</p></div><div class="data-row-side">${status(d.status)}${btn('donation-detail',ops?'접수·상세':'진행 보기','',`data-id="${d.id}"`)}</div></div>`).join('')}</div>`:empty('아직 기부 내역이 없어요','나눌 물건이 있다면, 마음부터 전해 보세요.','<a href="#/donate" class="secondary-btn">현물 기부 시작하기</a>')}
function studioPage(){if(db.role!=='admin')return empty('운영팀을 위한 공간이에요','라이브 송출 기능은 최고관리자 콘솔에서만 제공됩니다.');return consoleTitle('방긋 라이브 스튜디오','방송 상품과 기관을 연결하고 라이브 운영을 준비합니다.',status(db.live.status))+`<div class="studio-preview"><img src="${asset('bazaar')}" alt="라이브 바자회 스튜디오 예시"><video id="camera-preview" autoplay muted playsinline hidden></video><div>${icon('camera')}<br><span>${db.live.status==='진행 중'?'방송 진행 시뮬레이션':'카메라를 켜서 화면을 확인하세요'}</span><br><small>외부 송출 미연결</small></div></div><div class="button-group mt-20">${btn('camera',icon('camera')+' 카메라 미리보기','secondary-btn')}${btn('camera-off','카메라 끄기','secondary-btn')}</div><form id="studio-form" class="mt-20"><label class="field">방송 제목<input name="title" value="${esc(db.live.title)}" maxlength="60" required></label><label class="field">함께하는 기관<select name="org">${db.orgs.map(o=>`<option value="${o.id}" ${o.id===db.live.org?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label><div class="field">방송에서 소개할 상품${db.products.map(p=>`<label class="check-line" style="margin:2px 0"><input type="checkbox" name="products" value="${p.id}" ${db.live.products.includes(p.id)?'checked':''}>${esc(p.name)} · ${esc(org(p.org).name)}</label>`).join('')}</div><button class="primary-btn green full">방송 설정 저장</button></form><div class="button-group mt-20">${btn('broadcast',icon(db.live.status==='진행 중'?'pause':'live')+(db.live.status==='진행 중'?' 방송 체험 종료':' 방송 시작 체험'),'primary-btn',`data-state="${db.live.status}"`)}<a href="#/live" class="secondary-btn">구매자 화면 보기</a></div><div class="info-box warn">${icon('info')}<span>라이브 운영 UI 체험입니다. 카메라는 기기 내에서만 미리 보며 서버로 전송하지 않습니다. 실제 스트리밍 송출은 연동 전입니다.</span></div>`}
function roleOptions(){return `<div class="role-options">${[['buyer','bag','좋은 물건을 고르고 주문해요'],['individual','user','물건과 마음을 함께 전해요'],['company','building','현물 기부와 ESG 활동을 관리해요'],['agency','shop','기부 접수, 기관몰과 정산을 관리해요'],['admin','settings','방송·상품·배송·정산을 운영해요']].map(([k,i,l])=>btn('set-role',icon(i)+`<div><strong>${roleLabels[k]}</strong><small>${l}</small></div>`+icon('chevron'),'role-option',`data-role="${k}"`)).join('')}</div>`}
function openModal(title,body,wide=false){modalPrevious=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-header"><h2 id="modal-title">${title}</h2>${btn('close-modal',icon('close'),'icon-btn','aria-label="닫기"')}</div>${body}</section></div>`;document.body.classList.add('no-scroll');setTimeout(()=>$('#modal-root .modal')?.focus(),0)}
function closeModal(){if(!$('#modal-root').innerHTML)return;$('#modal-root').innerHTML='';document.body.classList.remove('no-scroll');modalPrevious?.isConnected&&modalPrevious.focus()}
function receiptMarkup(d){return `<div class="receipt-paper"><span class="mini-badge">화면 체험용 · 공식 증빙 아님</span><h3>기부 내역 확인</h3><dl><dt>기부자</dt><dd>${esc(d.donor)}</dd><dt>수령 기관</dt><dd>${esc(org(d.org).name)}</dd><dt>기부 물품</dt><dd>${esc(d.name)} · ${d.qty}개</dd><dt>참고 가액</dt><dd>${won(d.value)}</dd><dt>신청일</dt><dd>${d.date}</dd><dt>검토 상태</dt><dd>${esc(d.receipt)}</dd></dl><div class="receipt-watermark">SAMPLE</div><p style="font-size:10px;color:#9a9f90">이 문서는 방긋마켓 디자인 체험용 샘플로, 기부금 영수증이 아니며 세무 증빙 효력이 없습니다.</p></div>`}
function productModal(id,donationId){const d=db.donations.find(x=>x.id===donationId),p=product(id)||{name:d?.name||'',org:d?.org||'o1',donor:d?.donor||'',price:'',original:'',image:'hero',category:'리빙·주방',stock:d?.qty||1,condition:'미사용 새 상품',desc:''};openModal(id?'기부 상품 수정':'새로운 기부 상품 등록',`<form id="product-form" data-id="${id||''}" data-donation="${donationId||''}"><label class="field">상품명<input name="name" value="${esc(p.name)}" required maxlength="80"></label><div class="field-row"><label class="field">판매 가격 (원)<input type="number" name="price" min="1" step="1" value="${p.price}" required></label><label class="field">정상 가격 (원)<input type="number" name="original" min="1" step="1" value="${p.original}" required></label></div><label class="field">기부자<input name="donor" value="${esc(p.donor)}" required maxlength="50"></label><label class="field">연결 기관<select name="org">${db.orgs.map(o=>`<option value="${o.id}" ${p.org===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label><div class="field-row"><label class="field">수량<input type="number" name="stock" min="0" max="100000" value="${p.stock}" required></label><label class="field">카테고리<select name="category">${['패션·잡화','리빙·주방','뷰티·케어','도서·취미'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label></div><label class="field">상품 이미지<select name="image">${[['hero','기부 선물 상자'],['knit','데일리 그래픽 티셔츠'],['mug','도자기 머그'],['tote','토트백'],['serum','스킨케어'],['lamp','조명'],['book','도서'],['objects','생활용품 모음']].map(([v,l])=>`<option value="${v}" ${p.image===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">상품 상태<input name="condition" value="${esc(p.condition)}" required maxlength="50"></label><label class="field">상품 소개<textarea name="desc" maxlength="500">${esc(p.desc)}</textarea></label><button class="primary-btn full">상품 ${id?'저장':'등록'}</button></form>`,true)}
function donationModal(id){const d=db.donations.find(d=>d.id===id);if(!d)return;const ops=db.role==='admin'||db.role==='agency'&&db.orgId===d.org;openModal('마음이 이어지는 기부 내역',`<div class="report-card"><div class="split-row"><h3>${esc(d.name)} · ${d.qty}개</h3>${status(d.status)}</div><p>${esc(d.donor)} → ${esc(org(d.org).name)}</p><p class="small muted">접수번호 ${esc(d.id)}<br>신청일 ${d.date}<br>참고 가액 ${won(d.value)}<br>${esc(d.memo||'정성껏 준비한 물품을 전합니다.')}</p></div>${timeline(['기부 신청 접수','기관 확인·물품 검수','상품 등록·판매','판매 결과 확인','기관 정산 및 나눔 결과'])}${ops?`<div class="button-group">${d.status==='접수 대기'?btn('donation-advance','접수 승인','primary-btn green',`data-id="${id}"`):d.status==='입고 검수'?btn('donation-advance','물품 검수 완료','primary-btn green',`data-id="${id}"`):d.status==='상품 등록 대기'&&['admin','agency'].includes(db.role)?btn('donation-product','기부 상품 등록','primary-btn',`data-id="${id}"`):''}${btn('receipt-view','영수증 검토 상태','secondary-btn',`data-id="${id}"`)}</div>`:''}`)}
function matchingModal(id){let chosen=db.donations.find(d=>d.id===id)||db.donations[0];openModal('기부자·기관·상품 연결',`<form id="matching-form"><label class="field">기부 신청 선택<select name="donation" id="match-donation">${db.donations.map(d=>`<option value="${d.id}" ${chosen.id===d.id?'selected':''}>${esc(d.donor)} · ${esc(d.name)}</option>`).join('')}</select></label><label class="field">수령 기관<select name="org" id="match-org">${db.orgs.map(o=>`<option value="${o.id}" ${chosen.org===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label><label class="field">함께 연결할 판매 상품 (선택)<select name="product"><option value="">기부 신청의 기관만 변경</option>${db.products.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.donor)}</option>`).join('')}</select><small>상품을 선택하면 해당 상품의 기부자와 기관도 함께 연결됩니다.</small></label><button class="primary-btn full green">매칭 저장</button></form>`)}
function settlementDetail(id,review=false){const s=db.settlements.find(s=>s.id===id);if(!s)return;openModal(review?'기관 정산 처리':'정산 명세서',`<div class="report-card"><h3>${esc(org(s.org).name)} · ${s.period}</h3><div class="metrics-list"><div><span>상품 판매금액</span><strong>${won(s.gross)}</strong></div><div><span>운영 비용</span><strong>${won(s.fee)}</strong></div><div><span>기관 전달금액</span><strong>${won(s.net)}</strong></div><div><span>처리 상태</span>${status(s.status)}</div></div></div><div class="info-box warn">${icon('info')}<span>데모 정산 명세서입니다. 완료 처리는 화면 상태만 변경하며 실제 송금은 발생하지 않습니다.</span></div>${review&&db.role==='admin'?btn('settlement-complete','정산 완료 처리 체험','primary-btn full green',`data-id="${id}"`):btn('export',icon('download')+' 명세 CSV 다운로드','secondary-btn full','data-kind="settlements"')}`)}
function orderModal(id,manage=false){const o=(db.role==='agency'?scopedSales():db.orders).find(o=>o.id===id);if(!o)return;openModal(manage?'주문·배송 관리':'주문 상세',`<span class="mini-badge">실제 결제가 없는 체험 주문</span><div class="report-card mt-20"><h3>${esc(o.id)}</h3>${o.items.map(i=>`<p>${esc(product(i.id)?.name||'상품')} · ${i.qty}개</p>`).join('')}<div class="metrics-list"><div><span>주문 금액</span><strong>${won(o.total)}</strong></div><div><span>받는 분</span><strong>${esc(o.name)}</strong></div><div><span>배송 상태</span>${status(o.status)}</div></div><p class="small">${esc(o.address)}<br>운송장: ${esc(o.tracking||'미등록')}</p></div>${manage&&db.role==='admin'?`<form id="order-form" data-id="${id}"><label class="field">주문 상태<select name="status">${['상품 준비 중','배송 중','배송 완료','구매 확정','주문 취소'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">운송장 번호<input name="tracking" value="${esc(o.tracking||'')}" maxlength="40" placeholder="DEMO123456"></label><button class="primary-btn full green">주문·배송 저장</button></form>`:''}`)}
function download(name,content,type='text/csv;charset=utf-8'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const csvCell=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};
function exportData(kind){let rows;if(kind==='orders')rows=[['주문번호','주문자','상품','금액','상태','운송장'],...scopedSales().map(o=>[o.id,o.name,o.items.map(i=>product(i.id)?.name+' x '+i.qty).join(' / '),o.total,o.status,o.tracking])];else if(kind==='settlements')rows=[['명세서','기관','기간','판매금액','운영비용','기관전달액','상태'],...scopedSettlements().map(s=>[s.id,org(s.org).name,s.period,s.gross,s.fee,s.net,s.status])];else rows=[['기부번호','기부자','기관','물품','수량','참고가액','진행상태','영수증'],...scopedDonations().map(d=>[d.id,d.donor,org(d.org).name,d.name,d.qty,d.value,d.status,d.receipt])];download('banggeut-demo-'+kind+'.csv','\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'));toast('체험 데이터 CSV를 다운로드했습니다.')}
function stopCamera(){if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}const v=$('#camera-preview');if(v){v.srcObject=null;v.hidden=true}}
async function cameraPreview(){if(db.role!=='admin')return;try{if(!navigator.mediaDevices?.getUserMedia)throw Error('unsupported');stopCamera();cameraStream=await navigator.mediaDevices.getUserMedia({video:true,audio:false});const v=$('#camera-preview');if(!v){stopCamera();return}v.srcObject=cameraStream;v.hidden=false;toast('카메라 미리보기 중입니다. 외부로 송출되지 않습니다.')}catch{toast('카메라를 사용할 수 없습니다. 기기와 브라우저 권한을 확인해 주세요.')}}
function addToCart(id,count=qty){const p=product(id);if(!p||p.stock<1){toast('현재 품절된 물품입니다.');return false}let c=db.cart.find(c=>c.id===id);if((c?.qty||0)+count>p.stock){toast('남은 수량보다 많이 담을 수 없어요.');return false}if(c)c.qty+=count;else db.cart.push({id,qty:count});save();return true}
function adjustCart(id,delta){const c=db.cart.find(c=>c.id===id),p=product(id);if(!c||!p)return;if(c.qty+delta>p.stock){toast('남은 수량을 확인해 주세요.');return}if(c.qty+delta<1)return;c.qty+=delta;save();render()}
const actions={
'close-modal':closeModal,'roles':()=>openModal('나의 방긋, 역할을 골라 보세요',`<p>각 계정의 화면을 자유롭게 체험해 보세요.<br>디자인 체험을 위한 역할 전환입니다.</p>${roleOptions()}`),
'set-role':el=>{const role=el.dataset.role;if(!roleLabels[role])return;stopCamera();MarketCore.activateAccount(db,role);lastRole=role;consoleSection='dashboard';save();closeModal();if(route()===(role==='buyer'?'/my':'/console'))render(true);else location.hash=role==='buyer'?'/my':'/console';toast(roleLabels[role]+' 화면으로 전환했습니다.')},
'search':()=>{openModal('어떤 좋은 물건을 찾으세요?',`<form id="modal-search-form"><label class="field">상품·기관 검색<input name="query" placeholder="예: 머그, 초록나무" required autofocus></label><button class="primary-btn full green">검색하기</button></form>`);setTimeout(()=>$('#modal-search-form input')?.focus(),50)},
'slide':el=>{slide=Number(el.dataset.index);updateHero()},'slide-next':()=>{slide=(slide+1)%4;updateHero()},'slide-prev':()=>{slide=(slide+3)%4;updateHero()},'slide-pause':()=>{paused=!paused;updateHero()},
'home-category':el=>{homeCategory=el.dataset.category;render()},'shop-category':el=>{shopCategory=el.dataset.category;render()},'clear-search':()=>{shopCategory='전체';shopSearch='';render()},
'wish':el=>{const id=el.dataset.id;if(!product(id))return;db.wishes=db.wishes.includes(id)?db.wishes.filter(x=>x!==id):[...db.wishes,id];save();render();toast(db.wishes.includes(id)?'마음에 드는 물건을 담았어요.':'찜 목록에서 뺐어요.')},
'follow':el=>{const id=el.dataset.id;db.follows=db.follows.includes(id)?db.follows.filter(x=>x!==id):[...db.follows,id];save();render();toast(db.follows.includes(id)?'이 기관을 응원합니다.':'응원 목록이 변경되었습니다.')},
'alert':()=>{db.alerts=db.alerts.includes('next')?db.alerts.filter(x=>x!=='next'):[...db.alerts,'next'];save();render();toast(db.alerts.includes('next')?'브라우저 내 알림 목록에 담았습니다. 실제 푸시 알림은 연동 전입니다.':'알림 목록에서 삭제했습니다.')},
'org-tab':el=>{orgTab=el.dataset.tab;render()},'qty-minus':()=>{qty=Math.max(1,qty-1);render()},'qty-plus':el=>{qty=Math.min(Number(el.dataset.max),qty+1);render()},
'add-cart':el=>{if(addToCart(el.dataset.id)){render();toast('장바구니에 마음을 담았어요.')}},'buy':el=>{if(addToCart(el.dataset.id))location.hash='/checkout'},'cart-minus':el=>adjustCart(el.dataset.id,-1),'cart-plus':el=>adjustCart(el.dataset.id,1),'cart-remove':el=>{db.cart=db.cart.filter(c=>c.id!==el.dataset.id);save();render()},
'donor-type':el=>{donateDraft.type=el.dataset.type;render()},'donate-prev':()=>{const f=$('#donate-form');if(f){const data=Object.fromEntries(new FormData(f));donateDraft={...donateDraft,...data}}donateStep=Math.max(1,donateStep-1);render(true)},
'console-tab':el=>{if(consoleSection==='studio')stopCamera();consoleSection=el.dataset.section;render();$('#console-content')?.scrollIntoView({block:'start',behavior:'auto'})},
'donation-detail':el=>donationModal(el.dataset.id),
'donation-advance':el=>{const d=db.donations.find(d=>d.id===el.dataset.id);if(!d||!(db.role==='admin'||db.role==='agency'&&db.orgId===d.org))return;d.status=d.status==='접수 대기'?'입고 검수':'상품 등록 대기';save();closeModal();render();toast('기부 물품 상태를 변경했습니다.')},
'donation-product':el=>{if(db.role!=='admin')return;closeModal();productModal(null,el.dataset.id)},
'product-new':()=>{if(db.role==='admin')productModal()},'product-edit':el=>{if(db.role==='admin')productModal(el.dataset.id)},
'matching':el=>{if(db.role==='admin')matchingModal(el.dataset.id)},
'receipt-view':el=>{const d=db.donations.find(x=>x.id===el.dataset.id);if(!d)return;openModal('기부 내역과 영수증 검토',receiptMarkup(d)+`<div class="button-group mt-20">${db.role==='agency'&&d.org===db.orgId?btn('receipt-issue','샘플 발급 완료 처리','primary-btn green',`data-id="${d.id}"`):''}${btn('receipt-download',icon('download')+' 샘플 다운로드','secondary-btn',`data-id="${d.id}"`)}</div>`,true)},
'receipt-issue':el=>{const d=db.donations.find(x=>x.id===el.dataset.id);if(!d||db.role!=='agency'||d.org!==db.orgId)return;d.receipt='샘플 발급 완료';save();closeModal();render();toast('샘플 발급 상태로 변경했습니다. 공식 영수증은 아닙니다.')},
'receipt-download':el=>{const d=db.donations.find(x=>x.id===el.dataset.id);if(d)download('banggeut-sample-'+d.id+'.html','<!doctype html><html lang="ko"><meta charset="UTF-8"><title>기부 내역 샘플 · 공식 증빙 아님</title><body style="font-family:sans-serif;max-width:680px;margin:50px auto">'+receiptMarkup(d)+'</body></html>','text/html;charset=utf-8')},
'settlement-detail':el=>settlementDetail(el.dataset.id),'settlement-review':el=>{if(db.role==='admin')settlementDetail(el.dataset.id,true)},'settlement-request':el=>{const s=db.settlements.find(x=>x.id===el.dataset.id);if(!s||db.role!=='agency'||s.org!==db.orgId)return;if(s.status==='요청 접수'){settlementDetail(s.id);return}s.status='요청 접수';save();render();toast('정산 요청을 기록했습니다. 실제 송금은 발생하지 않습니다.')},
'settlement-complete':el=>{const s=db.settlements.find(x=>x.id===el.dataset.id);if(!s||db.role!=='admin')return;s.status='정산 완료';s.date=new Date().toLocaleDateString('ko-KR');save();closeModal();render();toast('정산 완료 상태로 변경했습니다. 실제 송금은 진행되지 않습니다.')},
'order-detail':el=>orderModal(el.dataset.id),'order-manage':el=>{if(db.role==='admin')orderModal(el.dataset.id,true)},
'export':el=>exportData(el.dataset.kind),
'logout':()=>{stopCamera();MarketCore.activateAccount(db,null);save();render();toast('체험 계정에서 나왔어요.')},
'mall-color':el=>{if(db.role!=='agency')return;activeOrg().color=el.dataset.color;$('#mall-form .color-choice .active')?.classList.remove('active');el.classList.add('active')},'mall-cover':el=>{if(db.role!=='agency')return;activeOrg().cover=el.dataset.cover;$('#mall-form .cover-options .active')?.classList.remove('active');el.classList.add('active')},
'camera':cameraPreview,'camera-off':()=>{stopCamera();toast('카메라를 껐습니다.')},
'broadcast':()=>{if(db.role!=='admin')return;db.live.status=db.live.status==='진행 중'?'종료':'진행 중';stopCamera();save();render();toast(db.live.status==='진행 중'?'방송 진행 화면으로 전환했습니다. 실제 송출은 연동 전입니다.':'방송 체험을 마쳤습니다.')},
'live-preview':()=>openModal('함께하면 더 방긋',`<img src="${asset('bazaar')}" alt="사람들이 함께하는 바자회" style="width:100%;border-radius:12px"><p>방긋마켓이 직접 진행할 라이브 바자회의 미리보기입니다. 상품을 둘러보고 주문하는 흐름을 체험할 수 있어요.</p><div class="info-box">${icon('live')}<span>현재 실시간 영상 송출은 연결되지 않았습니다.</span></div>`),
'member-toggle':el=>{if(db.role!=='admin')return;const m=db.members[Number(el.dataset.index)];if(m)m.status=m.status==='활성'?'이용 정지':'활성';save();render();toast('체험 계정 상태를 변경했습니다.')},
'notice-new':()=>openModal('나눔의 새 소식을 전해요',`<form id="notice-form"><label class="field">제목<input name="title" required maxlength="80" placeholder="따뜻한 소식을 한 줄로"></label><label class="field">내용<textarea name="body" required maxlength="800" placeholder="나눔 활동과 새로운 이야기를 들려주세요."></textarea></label><button class="primary-btn green full">소식 저장·게시</button></form>`),
'notice-toggle':el=>{const n=db.notices.find(n=>n.id===el.dataset.id);if(!n||!(db.role==='admin'||db.role==='agency'&&n.org===db.orgId))return;n.status=n.status==='게시 중'?'비공개':'게시 중';save();render();toast('소식 게시 상태를 변경했습니다.')},
'institution-new':()=>{if(db.role!=='admin')return;openModal('새로운 파트너 기관',`<form id="institution-form"><label class="field">기관명<input name="name" required maxlength="40"></label><label class="field">한 줄 소개<input name="tag" required maxlength="50"></label><label class="field">지역·활동 분야<input name="area" required placeholder="예: 서울 · 아동복지" maxlength="50"></label><label class="field">기관 소개<textarea name="description" maxlength="300" required></textarea></label><button class="primary-btn full green">체험 기관 등록</button></form>`)},
'banner-edit':el=>{if(db.role!=='admin')return;const i=Number(el.dataset.index),s={...slides[i],...db.banners[i]};openModal('메인 배너 '+(i+1)+' 수정',`<form id="banner-form" data-index="${i}"><label class="field">배너 제목 · 줄바꿈 가능<textarea name="title" required maxlength="60">${esc(s.title.replace(/<br>/g,'\n'))}</textarea></label><label class="field">소개 문구<textarea name="desc" required maxlength="100">${esc(s.desc.replace(/<br>/g,'\n'))}</textarea></label><label class="field">배너 이미지<select name="image">${[['hero','기부 선물 상자'],['community','마음을 전하는 손길'],['objects','좋은 생활용품'],['bazaar','바자회 현장 · 사람'],['people','함께 웃는 나눔 · 사람']].map(([v,l])=>`<option value="${v}" ${s.image===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="primary-btn full green">배너 저장</button></form>`)},
 'team-new':()=>openModal('함께할 담당자 추가',`<form id="team-form"><label class="field">이름<input name="name" required maxlength="40"></label><label class="field">이메일<input name="email" type="email" placeholder="team@example.com" required></label><label class="field">역할<select name="role"><option>기부 담당자</option><option>정산·증빙 담당자</option><option>기업 관리자</option></select></label><p class="small">화면 체험용입니다. 초대 이메일은 발송되지 않습니다.</p><button class="primary-btn full green">체험 담당자 추가</button></form>`),
 'team-remove':el=>{if(db.role!=='company')return;db.team.splice(Number(el.dataset.index),1);save();render();toast('담당자를 삭제했습니다.')},
 'reset-demo':()=>openModal('체험을 처음부터 다시',`<p>이 브라우저에서 추가한 체험 주문·기부·설정을 지우고 처음 화면으로 돌아갑니다.</p>${btn('confirm-reset','체험 데이터 초기화','primary-btn full')}`),
 'confirm-reset':()=>{stopCamera();db=structuredClone(defaults);save();closeModal();location.hash='/';render(true);toast('처음의 방긋마켓으로 돌아왔어요.')},
 'about':()=>openModal('물건에 마음을, 일상에 방긋.',`<img src="${asset('people')}" alt="바자회에서 웃는 사람들" style="width:100%;border-radius:12px"><p>방긋마켓은 개인·기업의 현물 기부와 사회복지기관을 연결하고, 자체 라이브 바자회와 상시 판매를 통해 물건의 가치를 나눔으로 이어가는 서비스입니다.</p><p>기부 접수와 영수증 검토는 수령 기관이, 판매와 라이브 운영은 방긋마켓이 맡는 흐름으로 설계했습니다.</p><a href="#/impact" class="primary-btn full green" data-action="close-modal">나눔의 흐름 알아보기</a>`),
 'faq':()=>openModal('궁금한 마음을 풀어 드려요',`<details open><summary>개인도 현물을 기부할 수 있나요?</summary><p>개인과 기업 모두 기부 신청 화면에서 물품과 기관을 선택할 수 있습니다. 기관의 확인과 검수 절차로 연결됩니다.</p></details><details><summary>기부한 물건은 누가 판매하나요?</summary><p>기관 쇼핑몰에서 기관이 상품과 주문·배송을 관리하고, 방긋마켓은 자체 라이브 바자회를 운영합니다. 외부 셀러의 입점·송출 없이 최고관리자가 방송을 관리합니다.</p></details><details><summary>기관은 어떻게 정산을 확인하나요?</summary><p>기관 콘솔의 판매 내역과 정산 관리에서 상품별 판매금액, 운영 비용과 전달 예정액을 볼 수 있습니다.</p></details><details><summary>기부금 영수증은 어떻게 확인하나요?</summary><p>수령 기관이 기부 물품과 증빙을 검토합니다. 현재 화면은 샘플 내역과 발급 상태를 확인하는 체험판입니다.</p></details><details><summary>실제 주문이나 결제가 가능한가요?</summary><p>현재는 디자인 체험 버전입니다. 실제 계정 인증·결제·송출·배송·계좌이체·공식 증빙 발급은 연동 전입니다.</p></details>`),
 'contact':()=>openModal('방긋에게 이야기해 주세요',`<p>운영 시간: ${esc(db.settings.support)}</p><form id="contact-form"><label class="field">문의 유형<select name="type"><option>현물 기부 문의</option><option>기관 참여 문의</option><option>주문·배송 문의</option><option>기타</option></select></label><label class="field">문의 내용<textarea name="body" required maxlength="500" placeholder="문의 화면을 체험해 보세요."></textarea></label><p class="small">전송되지 않는 문의 UI 체험입니다.</p><button class="primary-btn full green">문의 작성 체험</button></form>`)
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){const action=actions[el.dataset.action];if(action){if(el.tagName!=='A')e.preventDefault();action(el)}}else if(e.target.classList.contains('modal-overlay'))closeModal();const start=e.target.closest('[data-donor-start]');if(start){donateDraft={type:start.dataset.donorStart==='company'?'기업':'개인',org:'o1'};donateStep=1}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();const modal=$('#modal-root .modal');if(e.key==='Tab'&&modal){const all=[...modal.querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled);if(all.length){const first=all[0],last=all.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===modal)){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}});
document.addEventListener('change',e=>{if(e.target.id==='product-sort'){shopSort=e.target.value;render()}if(e.target.id==='agency-switch'){MarketCore.activateAccount(db,'agency',e.target.value);save();render()}if(e.target.id==='match-donation'){const d=db.donations.find(d=>d.id===e.target.value);if(d)$('#match-org').value=d.org}});
document.addEventListener('input',e=>{if(e.target.id==='org-search'){const q=e.target.value.trim();const os=db.orgs.filter(o=>(o.name+o.area+o.tag).includes(q));$('#org-results').innerHTML=os.length?os.map(orgCard).join(''):empty('검색된 기관이 없어요','기관명이나 지역으로 다시 찾아보세요.')}});
document.addEventListener('submit',e=>{const f=e.target;if(!f.id)return;e.preventDefault();const fd=new FormData(f),v=Object.fromEntries(fd);switch(f.id){
case 'search-form':case 'modal-search-form':shopSearch=(v.query||'').trim();shopCategory='전체';closeModal();if(route()==='/shop')render();else location.hash='/shop';break;
case 'donate-form':if(donateStep<3){donateDraft={...donateDraft,...v};if(donateStep===2){donateDraft.qty=Number(v.qty);donateDraft.value=Number(v.value||0);donateDraft.receipt=fd.has('receipt')}donateStep++;render(true)}else{const id='D-'+Date.now().toString().slice(-8);if(!db.role)MarketCore.activateAccount(db,donateDraft.type==='기업'?'company':'individual');db.donations.unshift({...donateDraft,id,qty:Number(donateDraft.qty),value:Number(donateDraft.value||0),remaining:Number(donateDraft.qty),status:'접수 대기',receipt:donateDraft.receipt?'발급 검토 요청':'미요청',date:new Date().toLocaleDateString('ko-KR'),mine:true,ownerAccount:MarketCore.accountId(db)});save();openModal('마음을 전해 주셔서 고마워요.',`<div class="success-block"><div class="success-icon">${icon('check')}</div><h2>기부 신청 체험을 완료했어요.</h2><p>${esc(org(donateDraft.org).name)}에 전달할<br>${esc(donateDraft.name)} ${donateDraft.qty}개의 마음을 기록했습니다.<br>접수번호 ${id}</p>${btn('close-modal','신청 내역 확인하기','primary-btn full green')}</div>`);if(!db.role){db.role=donateDraft.type==='기업'?'company':'individual';save()}consoleSection='donations';donateStep=1;donateDraft={type:'개인',org:'o1'};location.hash=db.role==='buyer'?'/my':'/console'}break;
case 'checkout-form':{if(!db.cart.length){toast('장바구니를 먼저 확인해 주세요.');break}for(const c of db.cart){if(!product(c.id)||product(c.id).stock<c.qty){toast('상품의 남은 수량이 변경되었어요. 장바구니를 확인해 주세요.');return}}const subtotal=db.cart.reduce((a,c)=>a+product(c.id).price*c.qty,0),shipping=subtotal>=50000?0:3000,id='B-'+Date.now().toString().slice(-9),byOrg={};for(const c of db.cart){const p=product(c.id);p.stock-=c.qty;byOrg[p.org]=(byOrg[p.org]||0)+p.price*c.qty}db.orders.unshift({id,name:v.name,address:v.address,items:structuredClone(db.cart),total:subtotal+shipping,status:'상품 준비 중',date:new Date().toLocaleDateString('ko-KR'),tracking:'',mine:true});for(const [orgId,gross]of Object.entries(byOrg)){const fee=Math.round(gross*Number(db.settings.fee)/100);db.settlements.unshift({id:'S-'+Date.now().toString().slice(-8)+'-'+orgId,org:orgId,gross,fee,net:gross-fee,status:'정산 대기',period:'체험 주문',date:new Date().toLocaleDateString('ko-KR')});org(orgId).raised+=gross}db.cart=[];save();location.hash='/my';openModal('주문에 마음을 더해 주셨어요.',`<div class="success-block"><div class="success-icon">${icon('smile')}</div><h2>주문 체험이 완료됐어요.</h2><p>주문번호 ${id}<br>실제 결제·배송은 발생하지 않았습니다.<br>마이 방긋에서 주문을 확인해 보세요.</p>${btn('close-modal','나의 주문 보기','primary-btn full green')}</div>`);break}
case 'chat-form':chatMessages.push(v.message);f.reset();render();break;
case 'product-form':{if(db.role!=='admin')return;if(Number(v.original)<Number(v.price)){f.elements.original.setCustomValidity('정상 가격은 판매 가격 이상으로 입력해 주세요.');f.elements.original.reportValidity();f.elements.original.addEventListener('input',()=>f.elements.original.setCustomValidity(''),{once:true});return}const id=f.dataset.id||'p'+Date.now();const data={...v,id,price:Number(v.price),original:Number(v.original),stock:Number(v.stock)};const index=db.products.findIndex(p=>p.id===id);if(index>=0)db.products[index]=data;else db.products.unshift(data);if(f.dataset.donation){const d=db.donations.find(d=>d.id===f.dataset.donation);if(d)d.status='판매 중'}save();closeModal();render();toast('기부 상품을 저장했습니다.');break}
case 'matching-form':{if(db.role!=='admin')return;const d=db.donations.find(d=>d.id===v.donation);if(d){if(v.product)MarketCore.transferProduct(db,{role:'admin'},v.product,v.org,d.donor);d.org=v.org}save();closeModal();render();toast('기부자와 기관의 연결을 저장했습니다.');break}
case 'order-form':{if(db.role!=='admin')return;const o=db.orders.find(o=>o.id===f.dataset.id);if(o){o.status=v.status;o.tracking=v.tracking}save();closeModal();render();toast('주문·배송 상태를 저장했습니다.');break}
case 'mall-form':{if(db.role!=='agency')return;Object.assign(activeOrg(),v);save();render();toast('기관몰을 저장했습니다. 기관몰에서 확인해 보세요.');break}
case 'studio-form':{if(db.role!=='admin')return;const pids=fd.getAll('products');if(!pids.length){toast('방송에서 소개할 상품을 한 개 이상 선택해 주세요.');return}Object.assign(db.live,{title:v.title,org:v.org,products:pids});save();toast('라이브 방송 설정을 저장했습니다.');break}
case 'settings-form':if(db.role==='admin')Object.assign(db.settings,{...v,fee:Number(v.fee)});else if(db.role==='agency')Object.assign(activeOrg(),v);else Object.assign(db.profile,v);save();render();toast('설정을 저장했습니다.');break;
case 'notice-form':if(!['agency','admin'].includes(db.role))return;db.notices.unshift({...v,id:'N'+Date.now(),org:db.role==='agency'?db.orgId:null,date:new Date().toLocaleDateString('ko-KR'),status:'게시 중'});save();closeModal();render();toast('새 소식을 저장했습니다.');break;
case 'team-form':if(db.role!=='company')return;db.team.push(v);save();closeModal();render();toast('체험 담당자를 추가했습니다. 실제 초대는 발송되지 않았습니다.');break;
case 'institution-form':if(db.role!=='admin')return;db.orgs.push({...v,id:'o'+Date.now(),short:v.name,cover:'people',symbol:'♧',color:'#477560',goal:2000000,raised:0,followers:0});save();closeModal();render();toast('새 기관과 나눔가게를 만들었습니다.');break;
case 'banner-form':if(db.role!=='admin')return;db.banners[Number(f.dataset.index)]={title:esc(v.title).replace(/\n/g,'<br>'),desc:esc(v.desc).replace(/\n/g,'<br>'),image:v.image};save();closeModal();render();toast('메인 배너를 저장했습니다.');break;
case 'contact-form':closeModal();toast('문의 화면 체험을 완료했습니다. 외부로 전송되지 않았습니다.');break;
}});
function updateHero(){const h=$('.hero');if(h)h.innerHTML=heroHTML()}
function render(reset=false){const y=scrollY;currentRoute=route();let content;if(currentRoute==='/')content=home();else if(currentRoute==='/shop')content=shopPage();else if(currentRoute==='/institutions')content=institutions();else if(currentRoute.startsWith('/institution/'))content=orgPage(currentRoute.split('/')[2]);else if(currentRoute.startsWith('/product/'))content=productPage(currentRoute.split('/')[2]);else if(currentRoute==='/cart'||currentRoute==='/checkout')content=cartPage(currentRoute==='/checkout');else if(currentRoute.startsWith('/donate'))content=donatePage();else if(currentRoute==='/live')content=livePage();else if(currentRoute==='/impact')content=impactPage();else if(currentRoute==='/console')content=consolePage();else if(currentRoute==='/my')content=myPage();else content=header()+`<section class="section">${empty('이곳엔 아직 이야기가 없어요','방긋마켓의 좋은 물건을 만나러 가 볼까요?','<a href="#/" class="primary-btn">홈으로</a>')}</section>`+bottomNav();$('#app').innerHTML=content;rail();const orgRoute=currentRoute.startsWith('/institution/'),o=orgRoute?org(currentRoute.split('/')[2]):null;document.body.classList.toggle('institution-view',orgRoute);$('#app').style.setProperty('--green',o?.color||'#477560');$('.desktop-scene').style.backgroundImage=`linear-gradient(180deg,#f6f5ed 0%,#f6f5ed 43%,#f6f5edb0 70%,#f6f5ed45 100%),url('${asset(o?.cover||'people')}')`;document.title=(o?o.name+' · ':currentRoute==='/console'?roleLabels[db.role]+' 콘솔 · ':'')+'방긋마켓 · 라이브 바자회';window.scrollTo(0,reset?0:y)}
